package com.example.meetomxh;

import android.os.Bundle;
import android.text.InputType;
import android.widget.EditText;
import android.widget.LinearLayout;
import android.widget.Switch;
import android.widget.Toast;
import androidx.appcompat.app.AlertDialog;
import androidx.appcompat.app.AppCompatActivity;
import com.example.meetomxh.repositories.CommunityGroupRepository;
import com.example.meetomxh.supabase.Api;
import com.example.meetomxh.supabase.Forms;
import org.json.JSONArray;
import org.json.JSONObject;

public class CommunityGroupAdminActivity extends AppCompatActivity {
    private String groupId; private LinearLayout form;
    @Override protected void onCreate(Bundle b){super.onCreate(b);groupId=getIntent().getStringExtra("group_id");home();}
    private void home(){form=Forms.start(this,"Quản lý nhóm");Forms.button(form,"Yêu cầu tham gia",()->requests());Forms.button(form,"Bài viết chờ duyệt",()->pendingPosts());Forms.button(form,"Thành viên",()->startActivity(new android.content.Intent(this,CommunityGroupMembersActivity.class).putExtra("group_id",groupId)));Forms.button(form,"Lời mời",()->startActivity(new android.content.Intent(this,CommunityGroupInvitesActivity.class).putExtra("group_id",groupId)));Forms.button(form,"Danh sách bị cấm",()->bans());Forms.button(form,"Báo cáo",()->reports());Forms.button(form,"Cài đặt nhóm",()->settings());}
    private void requests(){form=Forms.start(this,"Yêu cầu tham gia");Forms.status(this,"Đang tải…");CommunityGroupRepository.requests(groupId,null,null,new CommunityGroupRepository.Callback<JSONArray>(){public void success(JSONArray rows){form.removeAllViews();if(rows.length()==0)Forms.status(CommunityGroupAdminActivity.this,"Không có yêu cầu đang chờ.");for(int i=0;i<rows.length();i++){JSONObject r=rows.optJSONObject(i);String id=r.optString("id"),uid=r.optString("user_id"),name=r.optString("display_name","Thành viên");Forms.button(form,name+" · Xem hồ sơ",()->startActivity(new android.content.Intent(CommunityGroupAdminActivity.this,ProfileActivity.class).putExtra("target_uid",uid)));Forms.button(form,"Duyệt · "+name,()->resolveRequest(id,"approve"));Forms.button(form,"Từ chối · "+name,()->resolveRequest(id,"reject"));}}public void error(String e){Forms.status(CommunityGroupAdminActivity.this,e+" · "+"Nhấn để thử lại");}});}
    private void resolveRequest(String id,String action){CommunityGroupRepository.action("resolve_group_request",Api.obj("p_request_id",id,"p_action",action),done("Đã xử lý yêu cầu",this::requests));}
    private void pendingPosts(){form=Forms.start(this,"Bài viết chờ duyệt");CommunityGroupRepository.posts(groupId,true,null,null,new CommunityGroupRepository.Callback<java.util.List<com.example.meetomxh.models.Post>>(){public void success(java.util.List<com.example.meetomxh.models.Post> rows){if(rows.isEmpty())Forms.status(CommunityGroupAdminActivity.this,"Không có bài chờ duyệt.");for(com.example.meetomxh.models.Post p:rows){Forms.status(CommunityGroupAdminActivity.this,p.getContent());Forms.button(form,"Duyệt bài",()->review(p.getPostId(),"approve"));Forms.button(form,"Từ chối bài",()->review(p.getPostId(),"reject"));}}public void error(String e){Forms.status(CommunityGroupAdminActivity.this,e);}});}
    private void review(String id,String action){CommunityGroupRepository.action("review_community_post",Api.obj("p_post_id",id,"p_action",action),done("Đã cập nhật bài viết",this::pendingPosts));}
    private void bans(){form=Forms.start(this,"Thành viên bị cấm");Api.run(()->(JSONArray)com.example.meetomxh.supabase.RpcClient.call("list_group_bans",Api.obj("p_group_id",groupId,"p_after_time",null,"p_after_id",null,"p_limit",50)),new Api.Callback<JSONArray>(){public void success(JSONArray rows){if(rows.length()==0)Forms.status(CommunityGroupAdminActivity.this,"Danh sách cấm đang trống.");for(int i=0;i<rows.length();i++){JSONObject r=rows.optJSONObject(i);String uid=r.optString("user_id");Forms.button(form,r.optString("display_name","Thành viên")+" · Bỏ cấm",()->CommunityGroupRepository.action("manage_group_member",Api.obj("p_group_id",groupId,"p_user_id",uid,"p_action","unban"),done("Đã bỏ cấm",CommunityGroupAdminActivity.this::bans)));}}public void error(String e){Forms.status(CommunityGroupAdminActivity.this,e);}});}
    private void reports(){form=Forms.start(this,"Báo cáo nhóm");Api.run(()->(JSONArray)com.example.meetomxh.supabase.RpcClient.call("list_group_reports",Api.obj("p_group_id",groupId,"p_after_time",null,"p_after_id",null,"p_limit",50)),new Api.Callback<JSONArray>(){public void success(JSONArray rows){if(rows.length()==0)Forms.status(CommunityGroupAdminActivity.this,"Không có báo cáo đang mở.");for(int i=0;i<rows.length();i++){JSONObject r=rows.optJSONObject(i);String id=r.optString("id");Forms.status(CommunityGroupAdminActivity.this,r.optString("target_kind")+" · "+r.optString("reason_code")+"\n"+r.optString("details"));Forms.button(form,"Đánh dấu đã xử lý",()->reportAction(id,"resolve"));Forms.button(form,"Đóng báo cáo",()->reportAction(id,"dismiss"));}}public void error(String e){Forms.status(CommunityGroupAdminActivity.this,e);}});}
    private void reportAction(String id,String action){CommunityGroupRepository.action("resolve_group_report",Api.obj("p_group_id",groupId,"p_report_id",id,"p_action",action),done("Đã xử lý báo cáo",this::reports));}
    private void settings(){form=Forms.start(this,"Cài đặt nhóm");CommunityGroupRepository.get(groupId,new CommunityGroupRepository.Callback<JSONObject>(){public void success(JSONObject g){form.removeAllViews();EditText name=Forms.field(form,"Tên nhóm",g.optString("name"),InputType.TYPE_CLASS_TEXT);EditText desc=Forms.field(form,"Mô tả",g.optString("description"),InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE);EditText rules=Forms.field(form,"Quy định",g.optString("rules"),InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE);final String[] privacy={g.optString("privacy","public")};Forms.button(form,"Quyền riêng tư · "+privacy[0],()->new AlertDialog.Builder(CommunityGroupAdminActivity.this).setItems(new String[]{"Công khai","Riêng tư","Ẩn"},(d,n)->{privacy[0]=new String[]{"public","private","hidden"}[n];}).show());Switch listed=new Switch(CommunityGroupAdminActivity.this);listed.setText("Hiển thị trong tìm kiếm");listed.setChecked(g.optBoolean("listed",true));form.addView(listed);Switch approval=new Switch(CommunityGroupAdminActivity.this);approval.setText("Duyệt bài trước khi đăng");approval.setChecked(g.optBoolean("post_approval"));form.addView(approval);Forms.button(form,"Lưu cài đặt",()->{JSONObject args=Api.obj("p_group_id",groupId,"p_name",name.getText().toString(),"p_description",desc.getText().toString(),"p_privacy",privacy[0],"p_listed",listed.isChecked(),"p_rules",rules.getText().toString(),"p_post_approval",approval.isChecked());CommunityGroupRepository.action("update_community_group",args,done("Đã lưu cài đặt",CommunityGroupAdminActivity.this::settings));});}public void error(String e){Forms.status(CommunityGroupAdminActivity.this,e);}});}
    private CommunityGroupRepository.Callback<JSONObject> done(String message,Runnable refresh){return new CommunityGroupRepository.Callback<JSONObject>(){public void success(JSONObject o){Toast.makeText(CommunityGroupAdminActivity.this,message,Toast.LENGTH_SHORT).show();refresh.run();}public void error(String e){Toast.makeText(CommunityGroupAdminActivity.this,e,Toast.LENGTH_LONG).show();}};}
}
